window.LD=window.LD||{};window.LD["party/p1"]={"id":"p1","name":"The Newts of Ashfen","poss":"The Newts of Ashfen's","members":["h13","h7"],"leader":"h7","morale":99,"disposition":"honorable","motto":"Clean blades, clean consciences.","banner":{"c1":"#e8e8e8","c2":"#e8e8e8","emblem":"lizard"},"loc":"emberdeep","loc_name":"Emberdeep","goal":{"text":"to earn 1,700 silver between them before the season ends","kind":"purse","done":null,"progress":"1,408 of 1,700 silver","missed":true,"crew":"The Newts of Ashfen","party":"p1"},"vows":[{"text":"to share every coin","day":31,"state":"kept","ended":90,"through":true,"progress":"kept on day 30 of season 3","crew":"The Newts of Ashfen","party":"p1"}],"doing":"last seen delving into Emberdeep","progress":null,"today":["Fought 1 fight: won 1; 2 foes down.","XP: Bramble +982, Vex +1179 (level 24!).","Came away with 6 lava salt, 4 ember cores, 2 ore, a gem.","Ate 4 rations.","Drank a healing potion."],"fights_today":["f280"],"why":null,"founded_day":1,"founded_season":1,"disbanded":null,"anthem":null,"renown":280,"season":{"wins":15,"bosses":0,"floors":4,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30,"arguments":4},"career":{"wins":47,"bosses":1,"floors":23,"gold":0,"deaths":0,"fled":2,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":90,"arguments":7},"former":[],"fallen":[],"travel":null,"wagon":{"kind":"ox_wagon","name":"Mudlark","label":"ox wagon","seats":5,"haul":70,"comfort":0,"since":55,"desc":"Slow as a wedding, carries a house.","moves":true,"puller":{"kind":"ox","name":"Old Faithful","label":"ox","colour":"red","owner":null},"paid":[["Vex",71]]},"pace_gap":0,"rels":[{"party":"p4","score":100},{"party":"p3","score":100},{"party":"p2","score":56},{"party":"p6","score":55},{"party":"p5","score":44}],"events":[{"id":"e26","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Bramble and Vex shake on it at The Damp Lantern: they are now The Newts of Ashfen. (Honorable, by the look of them.)","heroes":["h13","h7"],"parties":["p1"],"loc":"ashfen"},{"id":"e400","day":11,"season":1,"sday":11,"kind":"road","imp":4,"text":"A silent old champion plays chess at a milestone on the road to Ashfen against anyone who stops. Bramble sits down, plays the game of their life, and is told it was a good one.","heroes":["h13","h7"],"parties":["p1"],"road":"ashfen~ashveil_crypts","road_rec":"r82"},{"id":"e744","day":20,"season":1,"sday":20,"kind":"road","imp":3,"text":"Captain Dorrit Salt teaches Bramble six sailor's knots on the verge, and one that is, she says, not for polite company.","heroes":["h13","h7"],"parties":["p1"],"road":"ashfen~ashveil_crypts","traveller":"salt","road_rec":"r147"},{"id":"e756","day":20,"season":1,"sday":20,"kind":"meet","imp":2,"text":"The Newts of Ashfen and The Mercy of Thornwall share a fire in the Ashveil Crypts. Bramble shares directions.","heroes":["h13","h7","h17","h11","h1"],"parties":["p1","p4"],"loc":"ashveil_crypts"},{"id":"e757","day":20,"season":1,"sday":20,"kind":"journey","imp":2,"text":"The Newts of Ashfen and The Mercy of Thornwall fall in together on the road to the Ashveil Crypts and spend the miles arguing about a shortcut that turned out to be a longcut.","heroes":["h13","h7","h17","h11","h1"],"parties":["p1","p4"]},{"id":"e769","day":21,"season":1,"sday":21,"kind":"delve","imp":1,"text":"The Newts of Ashfen descend into the Ashveil Crypts, partly explored (64%), map in hand.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e770","day":21,"season":1,"sday":21,"kind":"fight","imp":3,"text":"On floor 1 of the Ashveil Crypts, a Giant Rat and a Skeleton get in the Newts of Ashfen's way, briefly. The hit of the day was Bramble's Pinning Shot on the skeleton. Vex's High Ground kicked in when it counted. Loot: 4 bones.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f81","foes":["giant_rat","skeleton"],"where":"on floor 1 of The Ashveil Crypts","won":true,"close":false,"shape":"place","reworded":-14,"wx":"rain"},{"id":"e792","day":21,"season":1,"sday":21,"kind":"meet","imp":2,"text":"Amber Banner warns The Newts of Ashfen about what's lurking in the Ashveil Crypts. The Newts of Ashfen pretend to already know.","heroes":["h18","h4","h2","h13","h7"],"parties":["p2","p1"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e815","day":22,"season":1,"sday":22,"kind":"fight","imp":3,"text":"The Newts of Ashfen, in fine spirits lately, make short work of Risen Dead and a Skeleton Archer on floor 2 of the Ashveil Crypts. Vex called High Ground, and the line steadied. Loot: 2 grave dust, 2 bones.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f84","foes":["zombie","skeleton_archer"],"where":"on floor 2 of The Ashveil Crypts","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"rain"},{"id":"e852","day":23,"season":1,"sday":23,"kind":"fight","imp":1,"text":"With Bramble taking the worst of it, the Newts of Ashfen defeat Risen Dead and a Wraith on floor 3 of the Ashveil Crypts. The risen dead couldn't see a thing after Bramble's Smoke Bomb.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f87","foes":["zombie","wraith"],"where":"on floor 3 of The Ashveil Crypts","won":true,"close":false,"shape":"hero","reworded":-37,"wx":"rain"},{"id":"e853","day":23,"season":1,"sday":23,"kind":"ability","imp":2,"text":"Bramble sits so still by the stream at the Ashveil Crypts that a heron lands beside them. They fish side by side. The heron gets a trout; Bramble gets a fox, and a pelt.","heroes":["h13"],"parties":["p1"],"loc":"ashveil_crypts","skill":"still_as_a_heron","sk":"Still as a Heron","rule":true,"wx":"rain"},{"id":"e854","day":23,"season":1,"sday":23,"kind":"night","imp":2,"text":"Something small and clever gets into The Newts of Ashfen's camp in the Ashveil Crypts overnight. Vex wakes up 4 silver and 3 rations lighter.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e866","day":23,"season":1,"sday":23,"kind":"meet","imp":2,"text":"Duren and Bramble swap stories in the Ashveil Crypts while The Azure Gravediggers and The Newts of Ashfen swap rumours.","heroes":["h3","h15","h5","h9","h13","h7"],"parties":["p3","p1"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e887","day":24,"season":1,"sday":24,"kind":"fight","imp":3,"text":"Win number four in a row: the Newts of Ashfen beat a Bone Construct on floor 4 of the Ashveil Crypts. Pinning Shot from Vex left the bone construct reeling. Loot: 21 bones, 5 crypt-caps.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f92","foes":["bone_construct"],"where":"on floor 4 of The Ashveil Crypts","won":true,"close":false,"shape":"streak","reworded":-26,"wx":"rain"},{"id":"e888","day":24,"season":1,"sday":24,"kind":"treasure","imp":3,"text":"A dead adventurer on floor 4 of the Ashveil Crypts won't be needing 105 silver, a gem and a Goblin's Lucky Spoon any more. Bramble takes it, with thanks.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e906","day":25,"season":1,"sday":25,"kind":"fight","imp":3,"text":"A Wraith is waiting on floor 4 of the Ashveil Crypts, and the Newts of Ashfen cut it down. The wraith took Bramble's Pinning Shot full on and was never the same after. Without Vex's High Ground, this goes differently. Loot: 5 ectoplasm, 2 wraith-frost.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f95","foes":["wraith"],"where":"on floor 4 of The Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-19,"wx":"rain"},{"id":"e943","day":26,"season":1,"sday":26,"kind":"boss","imp":5,"text":"Seven rounds in, the Newts of Ashfen put an end to Vessimir the Unburied and a Bone Construct at the bottom of the Ashveil Crypts. Vessimir the Unburied lost a turn to Vex's Pinning Shot. Bramble accounted for 3 of them, mostly with Pan to the Face. Vex stopped to read the writing on the walls and is now worried about it. Loot: 185 silver each, 9 ectoplasm, 12 grave dust.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f102","foes":["necromancer","bone_construct"],"where":"at the bottom of The Ashveil Crypts","won":true,"close":true,"shape":"close","reworded":-26,"wx":"rain"},{"id":"e944","day":26,"season":1,"sday":26,"kind":"treasure","imp":1,"text":"Vessimir the Unburied's hoard, counted twice by torchlight: 11 gold pieces and 6 silver.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","in_fight":"f102","wx":"rain"},{"id":"e945","day":26,"season":1,"sday":26,"kind":"sniped","imp":3,"text":"Word reaches Amber Banner on floor 4 of the Ashveil Crypts: The Newts of Ashfen killed Vessimir the Unburied today. Nobody says much. The side passages still need mapping.","heroes":["h18","h4","h2","h13","h7"],"parties":["p2","p1"],"loc":"ashveil_crypts","snipers":["h13","h7"],"where":"inside","boss":"Vessimir the Unburied","in_fight":"f102","wx":"rain"},{"id":"e946","day":26,"season":1,"sday":26,"kind":"sniped","imp":3,"text":"Deep in the Ashveil Crypts, The Azure Gravediggers hear the roaring below stop. The Newts of Ashfen have reached Vessimir the Unburied first. The Azure Gravediggers stay and work the floors that are left.","heroes":["h3","h15","h5","h9","h13","h7"],"parties":["p3","p1"],"loc":"ashveil_crypts","snipers":["h13","h7"],"where":"inside","boss":"Vessimir the Unburied","in_fight":"f102","wx":"rain"},{"id":"e947","day":26,"season":1,"sday":26,"kind":"sniped","imp":3,"text":"Word reaches The Mercy of Thornwall on floor 3 of the Ashveil Crypts: The Newts of Ashfen killed Vessimir the Unburied today. Nobody says much. The side passages still need mapping.","heroes":["h17","h11","h1","h13","h7"],"parties":["p4","p1"],"loc":"ashveil_crypts","snipers":["h13","h7"],"where":"inside","boss":"Vessimir the Unburied","in_fight":"f102","wx":"rain"},{"id":"e948","day":26,"season":1,"sday":26,"kind":"race_won","imp":3,"text":"The Newts of Ashfen win the race to Vessimir the Unburied, ahead of Amber Banner and The Azure Gravediggers and The Mercy of Thornwall. The bets are paid out in Ashfen before the blood is dry.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","in_fight":"f102","wx":"rain"},{"id":"e971","day":26,"season":1,"sday":26,"kind":"big_move","imp":4,"text":"Seven rounds in, the Newts of Ashfen put an end to Vessimir the Unburied and a Bone Construct at the bottom of the Ashveil Crypts. On the table: Bramble +94 renown (5th to 1st) and Vex +92 (6th to 2nd). The Newts of Ashfen +135 party renown (4th to 1st among the crews).","heroes":["h13","h7"],"parties":["p1"],"cause":"e943","moves":[{"hero":"h13","gain":94,"from":5,"to":1},{"hero":"h7","gain":92,"from":6,"to":2}],"party_moves":[{"party":"p1","gain":135,"from":4,"to":1}],"fight":"f102"},{"id":"e981","day":27,"season":1,"sday":27,"kind":"delve_done","imp":1,"text":"The Newts of Ashfen come up after 7 days in the Ashveil Crypts. They got all the way to the bottom, mapped 97% of it and came away with 591 silver between them. Counting everyone's digging, the Ashveil Crypts is picked clean (100%).","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","days":7,"bottom":true,"rooms":[],"gold":591,"wx":"rain"},{"id":"e1038","day":28,"season":1,"sday":28,"kind":"journey","imp":2,"text":"The Mercy of Thornwall and The Newts of Ashfen walk to Ashfen together. Someone brings up what they'd do if they retired. Someone always does.","heroes":["h17","h11","h1","h13","h7"],"parties":["p4","p1"]},{"id":"e1051","day":28,"season":1,"sday":28,"kind":"ledger","imp":2,"text":"Counters and coin this week: 11 sales, 898 silver changing hands. Biggest haul: Bramble, 138 silver in Ashfen. Back up from the deep: The Black Vanguard (6 days in Thornmere Ruins), The Newts of Ashfen (7 days in the Ashveil Crypts).","heroes":["h13","h12"],"parties":["p5","p1"]},{"id":"e1065","day":29,"season":1,"sday":29,"kind":"talent","imp":2,"text":"Bramble whittles a tiny wolf for Vex by the fire. Vex calls it silly and keeps it in a breast pocket. Bramble puts it down to Whittling.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","skill":"whittler","wx":"rain"},{"id":"e1070","day":29,"season":1,"sday":29,"kind":"boss_race","imp":3,"text":"Word in the taverns: The Newts of Ashfen, The Azure Gravediggers and The Mercy of Thornwall are all after Mother Thornmere. Thornmere Ruins has one way down and room for one winner.","heroes":["h13","h7","h3","h15","h5","h9","h17","h11","h1"],"parties":["p1","p3","p4"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1073","day":29,"season":1,"sday":29,"kind":"meet","imp":2,"text":"The Newts of Ashfen warn The Mercy of Thornwall about what's lurking in Bleakmarsh. The Mercy of Thornwall pretends to already know.","heroes":["h13","h7","h17","h11","h1"],"parties":["p1","p4"],"loc":"bleakmarsh","wx":"rain"},{"id":"e1075","day":29,"season":1,"sday":29,"kind":"ability","imp":2,"text":"Vex turns off the road down a path nobody else can see. Two hours later the party is past the hills, rested and with dry feet.","heroes":["h7"],"parties":["p1"],"loc":"bleakmarsh","skill":"walker_of_all_roads","sk":"Walker of All Roads","rule":true,"wx":"rain"},{"id":"e1117","day":30,"season":1,"sday":30,"kind":"goal_missed","imp":3,"text":"Season's end, and The Newts of Ashfen came up short: earn 3,600 silver between them before the season ends (1,199 of 3,600 silver).","heroes":["h13","h7"],"parties":["p1"]},{"id":"e1123","day":30,"season":1,"sday":30,"kind":"season_end","imp":5,"text":"Season 1 ends. Bramble is Hero of the Season with 380 renown. The Newts of Ashfen finish as the top party.","heroes":["h13","h7"],"parties":["p1"]},{"id":"e1124","day":30,"season":1,"sday":30,"kind":"top_party","imp":4,"text":"TOP PARTY: The Newts of Ashfen (Bramble and Vex) end season 1 as the league's best crew, 496 party renown. Their season: 1 boss, 16 fights won and 11 floors explored.","heroes":["h13","h7"],"parties":["p1"]},{"id":"e1139","day":31,"season":2,"sday":1,"kind":"road","imp":3,"text":"Sister Rue lays her hands on Vex at the roadside and says the old words. Vex walks away lighter and ever so slightly scolded.","heroes":["h7","h13"],"parties":["p1"],"road":"ashfen~ashveil_crypts","traveller":"rue","road_rec":"r216"},{"id":"e1152","day":31,"season":2,"sday":1,"kind":"boss_race","imp":3,"text":"Word in the taverns: The Newts of Ashfen and The Azure Gravediggers are both after Vessimir the Unburied's Avenger. The Ashveil Crypts has one way down and room for one winner.","heroes":["h13","h7","h3","h15","h5","h9"],"parties":["p1","p3"],"loc":"ashveil_crypts"},{"id":"e1154","day":31,"season":2,"sday":1,"kind":"meet","imp":2,"text":"Duren and Vex swap stories in the Ashveil Crypts while The Azure Gravediggers and The Newts of Ashfen swap rumours.","heroes":["h3","h15","h5","h9","h13","h7"],"parties":["p3","p1"],"loc":"ashveil_crypts"},{"id":"e1155","day":31,"season":2,"sday":1,"kind":"journey","imp":2,"text":"The Newts of Ashfen and The Azure Gravediggers share the road to the Ashveil Crypts. By the second milestone they've agreed on nothing, least of all what they'd do if they retired.","heroes":["h13","h7","h3","h15","h5","h9"],"parties":["p1","p3"]},{"id":"e1162","day":31,"season":2,"sday":1,"kind":"campfire","imp":2,"text":"Bramble and Vex have shared a month of roads in The Newts of Ashfen. Ask either one about the other and settle in for a story.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e1168","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"The Newts of Ashfen stand before the league and swear it: to share every coin. The Annals are watching.","heroes":["h13","h7"],"parties":["p1"]},{"id":"e1178","day":32,"season":2,"sday":2,"kind":"delve","imp":1,"text":"The Newts of Ashfen descend into the Ashveil Crypts, partly explored (44%), map in hand.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e1179","day":32,"season":2,"sday":2,"kind":"fight","imp":1,"text":"The Newts of Ashfen see off a Skeleton and a Giant Rat on floor 1 of the Ashveil Crypts without much fuss. The hit of the day was Bramble's Pinning Shot on the skeleton. Without Vex's High Ground, this goes differently. Loot: 5 bones, 2 crypt-caps, a rat haunch.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f109","foes":["skeleton","giant_rat"],"where":"on floor 1 of The Ashveil Crypts","won":true,"close":false,"shape":"plain","reworded":-18},{"id":"e1180","day":32,"season":2,"sday":2,"kind":"ability","imp":2,"text":"Vex swears Bramble hasn't moved since lunch. Then one arrow, one deer, a bundle of pelts, and a camp that sleeps very well.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","skill":"still_as_a_heron","sk":"Still as a Heron","rule":true},{"id":"e1198","day":32,"season":2,"sday":2,"kind":"talent","imp":1,"text":"Vex lays an ear to the floor at the Ashveil Crypts and announces water, two rooms down. There is water, two rooms down. Spelunker: a ranger's patience, mostly.","heroes":["h7"],"parties":["p1"],"loc":"ashveil_crypts","skill":"spelunker"},{"id":"e1200","day":32,"season":2,"sday":2,"kind":"campfire","imp":1,"text":"Vex and Bramble walk point together all afternoon and say about nine words. Good words.","heroes":["h7","h13"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e1210","day":33,"season":2,"sday":3,"kind":"fight","imp":2,"text":"The Newts of Ashfen cut down Risen Dead, a Skeleton and a Skeleton Archer on floor 2 of the Ashveil Crypts, again. The skeleton took Vex's Pinning Shot full on and was never the same after. Bramble's Smoke Bomb turned the fight. Loot: 2 grave dust, 2 remains, 8 bones.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f114","foes":["zombie","skeleton","skeleton_archer"],"where":"on floor 2 of The Ashveil Crypts","won":true,"close":false,"shape":"again","reworded":-7},{"id":"e1225","day":33,"season":2,"sday":3,"kind":"talent","imp":1,"text":"Vex trades rations with a kobold through a barred door at the Ashveil Crypts. Both sides are wary. Both are fed.","heroes":["h7"],"parties":["p1"],"loc":"ashveil_crypts","skill":"barterer"},{"id":"e1229","day":33,"season":2,"sday":3,"kind":"campfire","imp":1,"text":"Bramble catches Vex humming and doesn't say anything. That's a start.","heroes":["h7","h13"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e1245","day":34,"season":2,"sday":4,"kind":"treasure","imp":2,"text":"Bramble insists on checking one more passage on floor 3 of the Ashveil Crypts, and it opens onto a reliquary behind a false wall: 1 gold piece and 18 silver.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e1283","day":35,"season":2,"sday":5,"kind":"fight","imp":1,"text":"The Newts of Ashfen send a Wraith back to its rest on floor 4 of the Ashveil Crypts. Bramble closed it out with Pan to the Face on the wraith. Loot: 5 ectoplasm, 1 trinket.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f124","foes":["wraith"],"where":"on floor 4 of The Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-14,"wx":"storm"},{"id":"e1284","day":35,"season":2,"sday":5,"kind":"ambush","imp":2,"text":"Two Giant Rats come at the Newts of Ashfen's camp in the Ashveil Crypts in the middle of the night, and the Newts of Ashfen dispatch them. The giant rat went down to Vex's Pinning Shot. Without Bramble's Smoke Bomb, this goes differently. Loot: 1 fang.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f125","foes":["giant_rat","giant_rat"],"where":"at their camp in The Ashveil Crypts, in the middle of the night","won":true,"close":false,"shape":"night","reworded":-32,"wx":"storm"},{"id":"e1318","day":36,"season":2,"sday":6,"kind":"sniped","imp":3,"text":"Deep in the Ashveil Crypts, The Newts of Ashfen hear the roaring below stop. The Azure Gravediggers have reached Vessimir the Unburied's Avenger first. The Newts of Ashfen stay and work the floors that are left.","heroes":["h13","h7","h3","h15","h5","h9"],"parties":["p1","p3"],"loc":"ashveil_crypts","snipers":["h3","h15","h5","h9"],"where":"inside","boss":"Vessimir the Unburied's Avenger","in_fight":"f128","wx":"fog"},{"id":"e1321","day":36,"season":2,"sday":6,"kind":"fight","imp":1,"text":"Win number eleven in a row: the Newts of Ashfen see off a Wraith on floor 4 of the Ashveil Crypts. Vex put Pinning Shot into the wraith to end it, and lowered the bow. Loot: 4 ectoplasm.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f129","foes":["wraith"],"where":"on floor 4 of The Ashveil Crypts","won":true,"close":false,"shape":"streak","reworded":-28,"wx":"fog"},{"id":"e1322","day":36,"season":2,"sday":6,"kind":"talent","imp":2,"text":"Bramble bets Vex the washing-up on a pinecone at forty paces. Vex is up to the elbows in suds by moonrise. That's Wager Shot for you.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","skill":"wager_shot","wx":"fog"},{"id":"e1333","day":36,"season":2,"sday":6,"kind":"talent","imp":1,"text":"Vex finds room in her pack for one more thing at the Ashveil Crypts. Then another. Then a candelabra.","heroes":["h7"],"parties":["p1"],"loc":"ashveil_crypts","skill":"packmule","wx":"fog"},{"id":"e1342","day":37,"season":2,"sday":7,"kind":"treasure","imp":1,"text":"Vex insists on checking one more passage on floor 4 of the Ashveil Crypts, and it opens onto a collapsed side passage: 1 gold piece, 18 silver and a jar of wraith-frost.","heroes":["h7","h13"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e1343","day":37,"season":2,"sday":7,"kind":"ability","imp":2,"text":"Bramble sits so still at the edge of camp near the Ashveil Crypts that a moth lands on their bow. One shot at dusk: supper for all, and a pelt to keep.","heroes":["h13"],"parties":["p1"],"loc":"ashveil_crypts","skill":"still_as_a_heron","sk":"Still as a Heron","rule":true},{"id":"e1370","day":38,"season":2,"sday":8,"kind":"delve_done","imp":3,"text":"The Newts of Ashfen come up after 7 days in the Ashveil Crypts. They got all the way to the bottom, mapped 97% of it, found a reliquary behind a false wall and a collapsed side passage, disarmed 2 traps and came away with 56 silver between them. The Azure Gravediggers got the boss. The Newts of Ashfen got the rest. Counting everyone's digging, the Ashveil Crypts is picked clean (99%).","heroes":["h13","h7"],"parties":["p1"],"loc":"ashveil_crypts","days":7,"bottom":true,"rooms":["a reliquary behind a false wall","a collapsed side passage"],"gold":56},{"id":"e1390","day":38,"season":2,"sday":8,"kind":"argument","imp":2,"text":"It starts with whose idea the last dungeon was. It ends with Vex and Bramble sleeping on opposite sides of the fire.","heroes":["h7","h13"],"parties":["p1"]},{"id":"e1415","day":39,"season":2,"sday":9,"kind":"talent","imp":2,"text":"Travellers in the Ashfen inn queue up to ask Vex the best way home. (Walker of All Roads, if anyone's asking.)","heroes":["h7"],"parties":["p1"],"loc":"ashfen","skill":"walker_of_all_roads"},{"id":"e1420","day":39,"season":2,"sday":9,"kind":"campfire","imp":1,"text":"Bramble laughs at one of Vex's jokes, then looks annoyed about it.","heroes":["h7","h13"],"parties":["p1"],"loc":"ashfen"},{"id":"e1463","day":40,"season":2,"sday":10,"kind":"argument","imp":1,"text":"The Newts of Ashfen spend the evening listening to Bramble and Vex argue about Bramble's habit of humming during ambushes.","heroes":["h13","h7"],"parties":["p1"]},{"id":"e1479","day":41,"season":2,"sday":11,"kind":"gift","imp":2,"text":"Vex admired Bramble's Goblin's Lucky Spoon one too many times. Now it's Vex's.","heroes":["h13","h7"],"parties":["p1"],"loc":"thornmere_ruins"},{"id":"e1487","day":41,"season":2,"sday":11,"kind":"goal","imp":2,"text":"After a long night's talk, The Newts of Ashfen settle on a goal: to see the world: 6 different places before the season ends.","heroes":["h13","h7"],"parties":["p1"]},{"id":"e1509","day":42,"season":2,"sday":12,"kind":"delve","imp":1,"text":"The Newts of Ashfen descend into Thornmere Ruins, partly explored (48%).","heroes":["h13","h7"],"parties":["p1"],"loc":"thornmere_ruins"},{"id":"e1510","day":42,"season":2,"sday":12,"kind":"fight","imp":1,"text":"The Newts of Ashfen run into a Swamp Troll and a Will-o'-Wisp on floor 1 of Thornmere Ruins and come out on top. The last will-o'-wisp bolts. The hit of the day was Bramble's Pinning Shot on the swamp troll. Loot: 16 silver each, 2 troll hide, 6 herbs. Bramble, who has been afraid of deep water since childhood, does not run. Nobody says anything. Everybody noticed.","heroes":["h13","h7"],"parties":["p1"],"loc":"thornmere_ruins","fight":"f146","foes":["swamp_troll","wisp"],"where":"on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"plain","reworded":-20},{"id":"e1511","day":42,"season":2,"sday":12,"kind":"treasure","imp":2,"text":"Bramble kicks over a rotten crate on floor 1 of Thornmere Ruins. Out rolls 4 gold pieces, 39 silver and a Very Small Skull.","heroes":["h13","h7"],"parties":["p1"],"loc":"thornmere_ruins"},{"id":"e1530","day":43,"season":2,"sday":13,"kind":"fight","imp":2,"text":"The Newts of Ashfen handle 2 Swamp Trolls on floor 1 of Thornmere Ruins, again. Vex called High Ground, and the line steadied. Loot: 43 silver each, 2 troll hide, 14 herbs.","heroes":["h13","h7"],"parties":["p1"],"loc":"thornmere_ruins","fight":"f148","foes":["swamp_troll","swamp_troll"],"where":"on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"again","reworded":-7},{"id":"e1531","day":43,"season":2,"sday":13,"kind":"ambush","imp":2,"text":"It takes the Newts of Ashfen 6 rounds to barely beat 2 Swamp Trolls at their camp in Thornmere Ruins, in the middle of the night. Vex tied up the swamp troll with Pinning Shot at just the right moment. Bramble's Pan to the Face did the damage (2 times). Vex insisted on checking every corner twice. Annoying. Correct. \"Done,\" says Vex. (Brother Toad's blessing on Bramble seems to have held.) Loot: 30 silver each, 1 troll hide, 2 troll haunches.","heroes":["h13","h7"],"parties":["p1"],"loc":"thornmere_ruins","fight":"f149","foes":["swamp_troll","swamp_troll"],"where":"at their camp in Thornmere Ruins, in the middle of the night","won":true,"close":true,"shape":"close","reworded":-21},{"id":"e1563","day":44,"season":2,"sday":14,"kind":"fight","imp":2,"text":"The Newts of Ashfen, in fine spirits lately, barely beat 2 Swamp Trolls on floor 2 of Thornmere Ruins. The swamp troll couldn't see a thing after Bramble's Smoke Bomb. Vex's Pinning Shot did the damage (2 times). (Brother Toad's blessing on Vex seems to have held.) Loot: 34 silver each, 4 troll hide, 4 herbs.","heroes":["h13","h7"],"parties":["p1"],"loc":"thornmere_ruins","fight":"f155","foes":["swamp_troll","swamp_troll"],"where":"on floor 2 of Thornmere Ruins","won":true,"close":true,"shape":"mood","reworded":-25},{"id":"e1564","day":44,"season":2,"sday":14,"kind":"artifact","imp":3,"text":"Bramble, reigning Hero of the Season, pockets a spoon set in a ring, warm to the touch in Thornmere Ruins. Bramble feels stronger already.","heroes":["h13"],"parties":["p1"],"loc":"thornmere_ruins"},{"id":"e1576","day":44,"season":2,"sday":14,"kind":"meet","imp":2,"text":"The Azure Gravediggers warn The Newts of Ashfen about what's lurking in Thornmere Ruins. The Newts of Ashfen pretend to already know.","heroes":["h3","h15","h5","h9","h13","h7"],"parties":["p3","p1"],"loc":"thornmere_ruins"},{"id":"e1596","day":45,"season":2,"sday":15,"kind":"fight","imp":1,"text":"On floor 3 of Thornmere Ruins, a Swamp Troll gets in the Newts of Ashfen's way, briefly. Everything after Bramble's Pan to the Face went right. Loot: 9 silver each, 2 troll hide, 6 herbs.","heroes":["h13","h7"],"parties":["p1"],"loc":"thornmere_ruins","fight":"f162","foes":["swamp_troll"],"where":"on floor 3 of Thornmere Ruins","won":true,"close":false,"shape":"place","reworded":-17},{"id":"e1597","day":45,"season":2,"sday":15,"kind":"ability","imp":2,"text":"A hare sits up in the grass at Thornmere Ruins, looks right at Bramble, and decides Bramble is a stump. Supper. By morning a pelt is stretched to dry on a frame.","heroes":["h13"],"parties":["p1"],"loc":"thornmere_ruins","skill":"still_as_a_heron","sk":"Still as a Heron","rule":true},{"id":"e1603","day":45,"season":2,"sday":15,"kind":"meet","imp":2,"text":"Sela and Bramble swap stories in Thornmere Ruins while Amber Banner and The Newts of Ashfen swap rumours.","heroes":["h18","h4","h2","h13","h7"],"parties":["p2","p1"],"loc":"thornmere_ruins"},{"id":"e1615","day":46,"season":2,"sday":16,"kind":"fight","imp":1,"text":"It's a Swamp Troll against the Newts of Ashfen on floor 4 of Thornmere Ruins, and it isn't close. Bramble's Smoke Bomb left the swamp troll swinging at nothing. Without Vex's High Ground, this goes differently. Loot: 23 silver each, 2 troll hide, 7 herbs.","heroes":["h13","h7"],"parties":["p1"],"loc":"thornmere_ruins","fight":"f164","foes":["swamp_troll"],"where":"on floor 4 of Thornmere Ruins","won":true,"close":false,"shape":"foe","reworded":-26},{"id":"e1618","day":46,"season":2,"sday":16,"kind":"ambush","imp":2,"text":"Bramble hits hardest as the Newts of Ashfen dispatch a Swamp Troll and a Will-o'-Wisp at their camp in Thornmere Ruins, in the middle of the night. Vex's High Ground came at the right time for all of them. The others will say it was close. Bramble made sure it wasn't. Loot: 15 silver each, 2 troll hide, 7 herbs.","heroes":["h13","h7"],"parties":["p1"],"loc":"thornmere_ruins","fight":"f165","foes":["swamp_troll","wisp"],"where":"at their camp in Thornmere Ruins, in the middle of the night","won":true,"close":false,"shape":"hero","reworded":-24},{"id":"e1628","day":46,"season":2,"sday":16,"kind":"sniped","imp":3,"text":"Word reaches The Newts of Ashfen on floor 4 of Thornmere Ruins: Amber Banner killed Mother Thornmere today. Nobody says much. The side passages still need mapping.","heroes":["h13","h7","h18","h4","h2"],"parties":["p1","p2"],"loc":"thornmere_ruins","snipers":["h18","h4","h2"],"where":"inside","boss":"Mother Thornmere","in_fight":"f168"},{"id":"e1650","day":47,"season":2,"sday":17,"kind":"delve_done","imp":3,"text":"The Newts of Ashfen come up after 6 days in Thornmere Ruins. They got all the way to the bottom, mapped 51% of it, disarmed 1 trap and came away with 418 silver between them. No boss, but the place paid. Counting everyone's digging, Thornmere Ruins is picked clean (91%).","heroes":["h13","h7"],"parties":["p1"],"loc":"thornmere_ruins","days":6,"bottom":true,"rooms":[],"gold":418},{"id":"e1659","day":47,"season":2,"sday":17,"kind":"meet","imp":2,"text":"The Newts of Ashfen run into The Black Vanguard in Thornmere Ruins. Stories are exchanged, most of them exaggerated.","heroes":["h13","h7","h12","h8","h6"],"parties":["p1","p5"],"loc":"thornmere_ruins"},{"id":"e1667","day":48,"season":2,"sday":18,"kind":"curse","imp":4,"text":"Something is wrong with The Newts of Ashfen. Since Bramble picked up the Ring-Spoon, nobody trusts anybody, and Bramble won't put it down.","heroes":["h13"],"parties":["p1"],"loc":"thornmere_ruins"},{"id":"e1673","day":48,"season":2,"sday":18,"kind":"ambush","imp":2,"text":"The Newts of Ashfen run into 2 Risen Dead on the road to Bleakmarsh and come out on top. Bramble's Keyhole Shot went in deep, and the risen dead slowed down after that. Bramble was wherever the trouble was, every time. Vex spotted the tripwire before anyone stepped on it.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","fight":"f170","foes":["zombie","zombie"],"where":"on the road to Bleakmarsh","won":true,"close":false,"shape":"plain","reworded":-20},{"id":"e1674","day":48,"season":2,"sday":18,"kind":"talent","imp":1,"text":"Bramble spots smoke from somebody else's fire on the far ridge before dark, and moves the camp behind a rock. Eagle Eye, the way the old trappers taught it.","heroes":["h13"],"parties":["p1"],"loc":"bleakmarsh","skill":"eagle_eye"},{"id":"e1681","day":48,"season":2,"sday":18,"kind":"ability","imp":2,"text":"Vex hitches a ride on a hay cart she knew would be passing at noon, naps all the way, and steps off healed and smiling.","heroes":["h7"],"parties":["p1"],"loc":"bleakmarsh","skill":"walker_of_all_roads","sk":"Walker of All Roads","rule":true},{"id":"e1699","day":49,"season":2,"sday":19,"kind":"road","imp":3,"text":"Bramble, reigning Hero of the Season, climbs the deck of a ship that sits in a meadow near the road to Ashfen, and finds the captain's tea still warm.","heroes":["h13","h7"],"parties":["p1"],"road":"ashfen~bleakmarsh","road_rec":"r307"},{"id":"e1721","day":49,"season":2,"sday":19,"kind":"campfire","imp":2,"text":"Vex offers Bramble the dry side of the tent. Bramble accepts, suspiciously.","heroes":["h7","h13"],"parties":["p1"],"loc":"ashfen"},{"id":"e1740","day":50,"season":2,"sday":20,"kind":"bounty","imp":2,"text":"The Newts of Ashfen cash in a season's worth of trophies at the Carrbridge guild: about 226 silver a head.","heroes":["h13"],"parties":["p1"],"loc":"carrbridge","amount":226},{"id":"e1754","day":50,"season":2,"sday":20,"kind":"goal_progress","imp":2,"text":"The Newts of Ashfen are getting close: see the world: 6 different places before the season ends (4 of 6 places).","heroes":["h13","h7"],"parties":["p1"]},{"id":"e1831","day":52,"season":2,"sday":22,"kind":"meet","imp":2,"text":"Wren and Vex swap stories in Redcrag Hills while The Green Mercy and The Newts of Ashfen swap rumours.","heroes":["h19","h20","h10","h16","h13","h7"],"parties":["p6","p1"],"loc":"redcrag"},{"id":"e1834","day":52,"season":2,"sday":22,"kind":"talent","imp":1,"text":"Bramble points at a glint in a hedge a quarter mile ahead near Redcrag Hills. A spear tip. The crew takes the other lane.","heroes":["h13"],"parties":["p1"],"loc":"redcrag","skill":"eagle_eye"},{"id":"e1836","day":52,"season":2,"sday":22,"kind":"talent","imp":2,"text":"Vex takes a path nobody else can see and the party arrives a full day early.","heroes":["h7"],"parties":["p1"],"loc":"redcrag","skill":"walker_of_all_roads"},{"id":"e1837","day":52,"season":2,"sday":22,"kind":"ability","imp":2,"text":"Vex takes Bramble and the rest along an old smugglers' path: flat, shady, with a spring halfway. They arrive in better shape than they set out.","heroes":["h7","h13"],"parties":["p1"],"loc":"redcrag","skill":"walker_of_all_roads","sk":"Walker of All Roads","rule":true},{"id":"e1841","day":52,"season":2,"sday":22,"kind":"argument","imp":4,"text":"Vex and Bramble have had the same argument three times now. This time Vex just walks away mid-sentence, which is worse. The campfire now has a line down the middle.","heroes":["h7","h13"],"parties":["p1"]},{"id":"e1848","day":52,"season":2,"sday":22,"kind":"goal_done","imp":4,"text":"GOAL: The Newts of Ashfen set out to see the world: 6 different places before the season ends, and they have done it, with 8 days to spare. It was Vex's idea in the first place. XP: Bramble +960, Vex +960 (level 19!).","heroes":["h13","h7"],"parties":["p1"],"xp":{"h13":960,"h7":960}},{"id":"e1864","day":53,"season":2,"sday":23,"kind":"fight","imp":3,"text":"In Redcrag Hills, the Newts of Ashfen are routed by 4 Drakes. Bramble covered the retreat. Vex has to be dragged out. Injured: Vex (concussion).","heroes":["h13","h7"],"parties":["p1"],"loc":"redcrag","fight":"f183","foes":["drake","drake","drake"],"where":"in Redcrag Hills","won":false,"close":true,"shape":"place","reworded":14},{"id":"e1865","day":53,"season":2,"sday":23,"kind":"ability","imp":1,"text":"Bramble waits two hours in the reeds by Redcrag Hills and comes back with a pelt and enough meat to quiet every stomach.","heroes":["h13"],"parties":["p1"],"loc":"redcrag","skill":"still_as_a_heron","sk":"Still as a Heron","rule":true},{"id":"e1866","day":53,"season":2,"sday":23,"kind":"night","imp":2,"text":"A tinker trades The Newts of Ashfen's camp in Redcrag Hills a kettle for a story, then tells one back: something under Frostspire is still awake.","heroes":["h13","h7"],"parties":["p1"],"loc":"redcrag"},{"id":"e1918","day":55,"season":2,"sday":25,"kind":"curse","imp":2,"text":"Bramble still won't put down the Ring-Spoon. 7 days now. The others have stopped asking.","heroes":["h13"],"parties":["p1"],"loc":"ironhaven"},{"id":"e1919","day":55,"season":2,"sday":25,"kind":"curse","imp":5,"text":"Prelate Gaudin takes the Ring-Spoon from Bramble's shaking hands, says some very old words over it, and breaks it. 38 silver, and worth every coin.","heroes":["h13"],"parties":["p1"],"loc":"ironhaven"},{"id":"e1932","day":55,"season":2,"sday":25,"kind":"wagon","imp":3,"text":"The Newts of Ashfen roll out of Ironhaven in an ox wagon called Mudlark, 71 silver between them. Vex paid for all of it.","heroes":["h13","h7"],"parties":["p1"],"loc":"ironhaven"},{"id":"e1933","day":55,"season":2,"sday":25,"kind":"contract","imp":2,"text":"Ironhaven expects raiders in two nights. The Newts of Ashfen sign on to hold the walls.","heroes":["h13","h7"],"parties":["p1"],"loc":"ironhaven"},{"id":"e1937","day":55,"season":2,"sday":25,"kind":"talent","imp":1,"text":"Bramble keeps the egg in their lap all evening at Ironhaven. The regulars start a betting pool.","heroes":["h13"],"parties":["p1"],"loc":"ironhaven"},{"id":"e1966","day":56,"season":2,"sday":26,"kind":"ambush","imp":2,"text":"Two Bandit Archers, the Raiders' Captain and a Bandit learn the hard way not to bother the Newts of Ashfen on the walls of Ironhaven. Bramble drew, held, and let Keyhole Shot go. The bandit archer never saw it. Vex accounted for 3 of them, mostly with Pinning Shot. Loot: 55 silver each, 6 stolen goods, 1 gem.","heroes":["h13","h7"],"parties":["p1"],"loc":"kingsroad","fight":"f189","foes":["bandit_captain","bandit_archer","bandit"],"where":"on the walls of Ironhaven","won":true,"close":true,"shape":"foe","reworded":-23},{"id":"e1967","day":56,"season":2,"sday":26,"kind":"contract","imp":4,"text":"THE WALLS HELD. Raiders hit Ironhaven at midnight and The Newts of Ashfen were waiting. By dawn the town is ringing its bell in The Newts of Ashfen's honour.","heroes":["h13","h7"],"parties":["p1"],"loc":"ironhaven"},{"id":"e1999","day":57,"season":2,"sday":27,"kind":"road","imp":4,"text":"Captain Mabb asks, very formally, whether the Fourth-Best Company might join Bramble as hirelings. Bramble says no, kindly. They take it well and buy the mule a hat.","heroes":["h13","h7"],"parties":["p1"],"road":"carrbridge~ironhaven","traveller":"fourth_best","road_rec":"r371"},{"id":"e2024","day":58,"season":2,"sday":28,"kind":"talent","imp":2,"text":"Bramble practises on the crew's padlocks by firelight. Vex buys a better padlock. Lockpicking, the guild calls it.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","skill":"lockpicking","wx":"rain"},{"id":"e2039","day":58,"season":2,"sday":28,"kind":"meet","imp":2,"text":"Hazel and Vex swap stories in Bleakmarsh while The Black Vanguard and The Newts of Ashfen swap rumours.","heroes":["h12","h8","h6","h13","h7"],"parties":["p5","p1"],"loc":"bleakmarsh","wx":"rain"},{"id":"e2041","day":58,"season":2,"sday":28,"kind":"campfire","imp":2,"text":"Bramble learns how Vex takes milk. It's a small thing. It's noticed.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","wx":"rain"},{"id":"e2050","day":59,"season":2,"sday":29,"kind":"fight","imp":2,"text":"The Newts of Ashfen, in fine spirits lately, handle 2 Swamp Trolls in Bleakmarsh. The hit of the day was Vex's Pinning Shot on the swamp troll. Smoke Bomb, from Bramble, at exactly the right moment. Loot: 39 silver each, 4 troll hide, 4 herbs.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","fight":"f198","foes":["swamp_troll","swamp_troll"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"rain"},{"id":"e2070","day":59,"season":2,"sday":29,"kind":"gift","imp":2,"text":"Bramble gives Vex a Very Small Skull. \"For luck,\" Bramble says, and won't explain further.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","wx":"rain"},{"id":"e2089","day":60,"season":2,"sday":30,"kind":"fight","imp":1,"text":"The Newts of Ashfen cut down a Swamp Troll in Bleakmarsh without much fuss. Vex called High Ground, and the line steadied. Bramble did more than their share and started none of the trouble. Loot: 22 silver each, 1 troll hide, 3 troll haunches.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","fight":"f202","foes":["swamp_troll"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"plain","reworded":-18,"wx":"rain"},{"id":"e2090","day":60,"season":2,"sday":30,"kind":"night","imp":2,"text":"Someone leaves a scrap of map by The Newts of Ashfen's fire in Bleakmarsh in the night. It shows a door in the Sunken Vault that isn't on any other map.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","wx":"rain"},{"id":"e2106","day":60,"season":2,"sday":30,"kind":"meet","imp":2,"text":"The Mercy of Thornwall warns The Newts of Ashfen about what's lurking in Bleakmarsh. The Newts of Ashfen pretend to already know.","heroes":["h17","h11","h1","h13","h7"],"parties":["p4","p1"],"loc":"bleakmarsh","wx":"rain"},{"id":"e2109","day":60,"season":2,"sday":30,"kind":"ability","imp":2,"text":"Vex turns off the road down a path nobody else can see. Two hours later the party is past the hills, rested and with dry feet.","heroes":["h7"],"parties":["p1"],"loc":"bleakmarsh","skill":"walker_of_all_roads","sk":"Walker of All Roads","rule":true,"wx":"rain"},{"id":"e2179","day":61,"season":3,"sday":1,"kind":"talent","imp":2,"text":"Vex trades an Ironhaven baker a sourdough starter for a sack of flour. The baker's eyes light up.","heroes":["h7"],"parties":["p1"],"loc":"ironhaven","skill":"trail_baker"},{"id":"e2191","day":62,"season":3,"sday":2,"kind":"contract","imp":2,"text":"The Newts of Ashfen take down the poster in Ironhaven: Lady Rot is theirs. Or will be.","heroes":["h13","h7"],"parties":["p1"],"loc":"ironhaven"},{"id":"e2192","day":62,"season":3,"sday":2,"kind":"road","imp":3,"text":"Vex follows a line of small flames down the road for the first time until it reaches Hetty Brimble, who is humming softly to the last one.","heroes":["h7","h13"],"parties":["p1"],"road":"ironhaven~redcrag","traveller":"hetty","road_rec":"r412"},{"id":"e2193","day":62,"season":3,"sday":2,"kind":"ability","imp":2,"text":"Bramble sits so still by the stream at Redcrag Hills that a heron lands beside them. They fish side by side. The heron gets a trout; Bramble gets a fox, and a pelt.","heroes":["h13"],"parties":["p1"],"loc":"redcrag","skill":"still_as_a_heron","sk":"Still as a Heron","rule":true},{"id":"e2212","day":62,"season":3,"sday":2,"kind":"argument","imp":2,"text":"Bramble and Vex spend supper disagreeing about the party's name, politely at first.","heroes":["h13","h7"],"parties":["p1"]},{"id":"e2226","day":63,"season":3,"sday":3,"kind":"boss","imp":5,"text":"Win number four in a row: the Newts of Ashfen slay Lady Rot and a Kobold in Redcrag Hills. One Keyhole Shot from Bramble, and Lady Rot stopped being a problem. Vex's High Ground kicked in when it counted. Bramble went in first, as usual. \"The ninth sign was correct, then,\" says Bramble. Loot: 3 silver each, 3 drake scales, 3 drake flanks.","heroes":["h13","h7"],"parties":["p1"],"loc":"redcrag","fight":"f207","foes":["drake","kobold"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"streak","reworded":-26},{"id":"e2227","day":63,"season":3,"sday":3,"kind":"contract","imp":4,"text":"Lady Rot is dead. The Newts of Ashfen drag the proof into Ironhaven and the guild pays 26 gold pieces and 9 silver on the spot. The poster comes down to applause.","heroes":["h13","h7"],"parties":["p1"],"loc":"redcrag"},{"id":"e2267","day":64,"season":3,"sday":4,"kind":"meet","imp":1,"text":"The Green Mercy runs into The Newts of Ashfen on the road between Ironhaven and Redcrag Hills. Stories are exchanged, most of them exaggerated.","heroes":["h19","h20","h10","h16","h13","h7"],"parties":["p6","p1"],"loc":"ironhaven"},{"id":"e2268","day":64,"season":3,"sday":4,"kind":"campfire","imp":2,"text":"Bramble lends Vex a whetstone. It comes back cleaner than it left.","heroes":["h13","h7"],"parties":["p1"],"loc":"ironhaven"},{"id":"e2277","day":65,"season":3,"sday":5,"kind":"road","imp":4,"text":"Vex is shown the inside of the satchel by Lark at the season's end. It is full of other people's good news. Lark grins for the first time.","heroes":["h7","h13"],"parties":["p1"],"road":"carrbridge~ironhaven","traveller":"lark","road_rec":"r441"},{"id":"e2350","day":67,"season":3,"sday":7,"kind":"fight","imp":2,"text":"Two Risen Dead stir in Bleakmarsh, and the Newts of Ashfen handle them for good. It was Vex's Pinning Shot that dropped the risen dead. Bramble pulled a friend out of trouble and went back in for more. Loot: 8 grave dust, 3 remains, 7 crypt-caps.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","fight":"f222","foes":["zombie","zombie"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"foe","reworded":-26,"wx":"storm"},{"id":"e2351","day":67,"season":3,"sday":7,"kind":"talent","imp":2,"text":"Vex sorts tomorrow's post by road and by hill. Bramble helps and learns the hills.","heroes":["h7","h13"],"parties":["p1"],"loc":"bleakmarsh","skill":"couriers_coin","wx":"storm"},{"id":"e2360","day":67,"season":3,"sday":7,"kind":"ability","imp":2,"text":"Vex carries a merchant's sealed note past Bleakmarsh in half the usual time. 28 silver, and the merchant tells her what's selling where.","heroes":["h7"],"parties":["p1"],"loc":"bleakmarsh","skill":"couriers_coin","sk":"Courier's Coin","rule":true,"wx":"storm"},{"id":"e2365","day":67,"season":3,"sday":7,"kind":"talent","imp":1,"text":"Bramble keeps one arrow apart from the rest, wrapped in cloth. They won't say what it's for.","heroes":["h13"],"parties":["p1"],"loc":"bleakmarsh","skill":"the_last_arrow","wx":"storm"},{"id":"e2379","day":68,"season":3,"sday":8,"kind":"fight","imp":2,"text":"The Newts of Ashfen cut down 3 Giant Spiders and a Bog Crawler in Bleakmarsh, in the rain. The last giant spider decides enough is enough, and goes. Bramble's Smoke Bomb left the giant spider swinging at nothing. High Ground did more for this fight than the scoreboard shows. That was Vex. Loot: 6 chitin, a giant spider leg.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","fight":"f224","foes":["giant_spider","bog_crawler","giant_spider"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"weather","reworded":-42,"wx":"rain"},{"id":"e2392","day":68,"season":3,"sday":8,"kind":"talent","imp":1,"text":"Vex delivers a lost lamb to the right farm, because she knows which farm is the right farm. Vex puts it down to Courier's Coin.","heroes":["h7"],"parties":["p1"],"loc":"bleakmarsh","skill":"couriers_coin","wx":"rain"},{"id":"e2393","day":68,"season":3,"sday":8,"kind":"ability","imp":1,"text":"Vex walks an old king's road that has been grass for a century, its stones still flat under the turf. She arrives with her cuts healed and her head clear.","heroes":["h7"],"parties":["p1"],"loc":"bleakmarsh","skill":"walker_of_all_roads","sk":"Walker of All Roads","rule":true,"wx":"rain"},{"id":"e2422","day":69,"season":3,"sday":9,"kind":"gift","imp":2,"text":"Bramble gives Vex an Egg That Is Still Warm. \"For luck,\" Bramble says, and won't explain further.","heroes":["h13","h7"],"parties":["p1"],"loc":"ashfen","wx":"rain"},{"id":"e2424","day":69,"season":3,"sday":9,"kind":"talent","imp":1,"text":"An Ashfen chandler closing up shop gives Vex a cartload of rope. Vex will find a use. Vex always does.","heroes":["h7"],"parties":["p1"],"loc":"ashfen","skill":"bulk_trader","wx":"rain"},{"id":"e2441","day":70,"season":3,"sday":10,"kind":"road","imp":4,"text":"There is a road where there was a field yesterday. It runs due west and has milestones that count backwards. Vex walks it, and arrives somewhere known and strange.","heroes":["h7","h13"],"parties":["p1"],"road":"ashfen~bleakmarsh","road_rec":"r470"},{"id":"e2442","day":70,"season":3,"sday":10,"kind":"night","imp":2,"text":"Something small and clever gets into The Newts of Ashfen's camp in Bleakmarsh overnight. Vex wakes up 11 silver and 1 ration lighter.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh"},{"id":"e2476","day":71,"season":3,"sday":11,"kind":"fight","imp":2,"text":"In Bleakmarsh, 2 Bog Crawlers and a Swamp Troll get in the Newts of Ashfen's way, briefly. The last bog crawler takes off and isn't seen again. Somewhere around Bramble's Keyhole Shot, the other side stopped believing. Loot: 14 silver each, 1 troll hide, 6 herbs.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","fight":"f235","foes":["swamp_troll","bog_crawler","bog_crawler"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"place","reworded":-43},{"id":"e2477","day":71,"season":3,"sday":11,"kind":"night","imp":2,"text":"Bramble tells a ghost story by the fire in Bleakmarsh. Vex laughs at it, then moves her bedroll closer to the others.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh"},{"id":"e2500","day":71,"season":3,"sday":11,"kind":"ability","imp":2,"text":"Vex drops off a bundle of post on the way past Bleakmarsh. 15 silver, a thank-you, and gossip about prices in two other towns.","heroes":["h7"],"parties":["p1"],"loc":"bleakmarsh","skill":"couriers_coin","sk":"Courier's Coin","rule":true},{"id":"e2504","day":71,"season":3,"sday":11,"kind":"talent","imp":1,"text":"Bramble watches the treeline for an hour without moving. Vex checks they are still breathing. Chalk it up to Still as a Heron.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","skill":"still_as_a_heron"},{"id":"e2505","day":71,"season":3,"sday":11,"kind":"campfire","imp":2,"text":"Vex asks Bramble how Wayfinders and Deadeyes are supposed to work together. Neither knows. They work it out.","heroes":["h7","h13"],"parties":["p1"],"loc":"bleakmarsh"},{"id":"e2511","day":71,"season":3,"sday":11,"kind":"goal","imp":2,"text":"After a long night's talk, The Newts of Ashfen settle on a goal: to earn 1,700 silver between them before the season ends.","heroes":["h13","h7"],"parties":["p1"]},{"id":"e2525","day":72,"season":3,"sday":12,"kind":"fight","imp":2,"text":"The Newts of Ashfen, in fine spirits lately, cut down 2 Risen Dead and a Will-o'-Wisp in Bleakmarsh. Vex drew, held, and let Headshot go. The risen dead never saw it. Loot: 7 grave dust, 4 crypt-caps, 3 bottled wisplight.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","fight":"f239","foes":["zombie","wisp","zombie"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"fog"},{"id":"e2526","day":72,"season":3,"sday":12,"kind":"talent","imp":2,"text":"Vex reports the gossip from the next camp over. Bramble is gripped.","heroes":["h7","h13"],"parties":["p1"],"loc":"bleakmarsh","skill":"eavesdropper","wx":"fog"},{"id":"e2562","day":73,"season":3,"sday":13,"kind":"fight","imp":2,"text":"The Newts of Ashfen make it nine wins running, making short work of 2 Bog Crawlers in Bleakmarsh. The last bog crawler doesn't stay to see the end. Vex's High Ground came at the right time for all of them. Bramble kept two of them busy so nobody else had to. Loot: 6 chitin.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","fight":"f243","foes":["bog_crawler","bog_crawler"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"streak","reworded":-51,"wx":"fog"},{"id":"e2578","day":73,"season":3,"sday":13,"kind":"meet","imp":2,"text":"The Black Vanguard warns The Newts of Ashfen about what's lurking in Bleakmarsh. The Newts of Ashfen pretend to already know.","heroes":["h12","h8","h6","h13","h7"],"parties":["p5","p1"],"loc":"bleakmarsh","wx":"fog"},{"id":"e2615","day":74,"season":3,"sday":14,"kind":"talent","imp":1,"text":"An Ashfen postmistress waves a stack of letters at Vex. 'Going north?' Vex is always going north.","heroes":["h7"],"parties":["p1"],"loc":"ashfen","skill":"couriers_coin","wx":"fog"},{"id":"e2645","day":75,"season":3,"sday":15,"kind":"road","imp":2,"text":"The Muddy Boot Pack are roasting something on a stick when Vex comes along for the first time. They offer her a share. It is still moving a little.","heroes":["h7","h13"],"parties":["p1"],"road":"ashfen~bleakmarsh","traveller":"muddy_boot","road_rec":"r487"},{"id":"e2663","day":75,"season":3,"sday":15,"kind":"ability","imp":2,"text":"Vex knows a drovers' track that skips the worst of the climb. The crew strolls in fresh, bruises healing, wondering why nobody else uses it.","heroes":["h7"],"parties":["p1"],"loc":"bleakmarsh","skill":"walker_of_all_roads","sk":"Walker of All Roads","rule":true,"wx":"fog"},{"id":"e2667","day":75,"season":3,"sday":15,"kind":"argument","imp":2,"text":"Bramble and Vex of The Newts of Ashfen have a shouting match about who ate the last of the cheese.","heroes":["h13","h7"],"parties":["p1"]},{"id":"e2680","day":76,"season":3,"sday":16,"kind":"fight","imp":3,"text":"With Bramble hitting hardest, the Newts of Ashfen handle 3 Swamp Trolls in Bleakmarsh. The last swamp troll turns tail. The fight turned on Bramble's Keyhole Shot. Ask the others what won it: Vex's High Ground. Loot: 39 silver each, 6 troll hide, 7 herbs.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","fight":"f254","foes":["swamp_troll","swamp_troll","swamp_troll"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"hero","reworded":-35,"wx":"storm"},{"id":"e2681","day":76,"season":3,"sday":16,"kind":"fight","imp":1,"text":"The Newts of Ashfen run into 2 Bog Crawlers in Bleakmarsh and come out on top. Vex's last Headshot settled it. Whenever it looked bad, Bramble was already there. Loot: 8 chitin.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","fight":"f255","foes":["bog_crawler","bog_crawler"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"plain","reworded":-24,"wx":"storm"},{"id":"e2682","day":76,"season":3,"sday":16,"kind":"talent","imp":1,"text":"Bramble plays jacks with the Ashfen knucklebone and four pebbles. The knucklebone wins.","heroes":["h13"],"parties":["p1"],"loc":"bleakmarsh","wx":"storm"},{"id":"e2698","day":76,"season":3,"sday":16,"kind":"meet","imp":2,"text":"The Newts of Ashfen and Amber Banner share a fire in Bleakmarsh. Nobody draws steel, which counts as a good meeting these days.","heroes":["h13","h7","h18","h4","h2"],"parties":["p1","p2"],"loc":"bleakmarsh","wx":"storm"},{"id":"e2700","day":76,"season":3,"sday":16,"kind":"ability","imp":1,"text":"Bramble and Vex run a sack of urgent letters past Bleakmarsh at a jog. 24 silver at the far end, and a postmaster who reads them the market news as thanks.","heroes":["h7","h13"],"parties":["p1"],"loc":"bleakmarsh","skill":"couriers_coin","sk":"Courier's Coin","rule":true,"wx":"storm"},{"id":"e2702","day":76,"season":3,"sday":16,"kind":"argument","imp":1,"text":"It starts with whose idea the last dungeon was. It ends with Bramble and Vex sleeping on opposite sides of the fire.","heroes":["h13","h7"],"parties":["p1"]},{"id":"e2721","day":77,"season":3,"sday":17,"kind":"fight","imp":1,"text":"In Bleakmarsh again, for the eighth time in eleven days: the Newts of Ashfen make short work of 2 Bog Crawlers and a Swamp Troll. Vex's Pinning Shot finished the fight. Loot: 24 silver each, 3 troll hide, 3 troll haunches.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","fight":"f257","foes":["swamp_troll","bog_crawler","bog_crawler"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"again","reworded":-43,"wx":"storm"},{"id":"e2722","day":77,"season":3,"sday":17,"kind":"fight","imp":2,"text":"Two Giant Spiders and a Bog Crawler fall to the Newts of Ashfen in Bleakmarsh. The final blow was Bramble's Pinning Shot. Loot: 4 spider legs, 6 chitin, 3 bog crawler claws.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","fight":"f258","foes":["giant_spider","bog_crawler","giant_spider"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"foe","reworded":-5,"wx":"storm"},{"id":"e2724","day":77,"season":3,"sday":17,"kind":"night","imp":2,"text":"A carter with a broken wheel in Bleakmarsh pays for The Newts of Ashfen's help in gossip: the deep rooms of the Collapsed Mine are open again.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","wx":"storm"},{"id":"e2774","day":78,"season":3,"sday":18,"kind":"fight","imp":2,"text":"In Bleakmarsh, 2 Swamp Trolls and a Bog Crawler get in the Newts of Ashfen's way, briefly. The bog crawler had been trouble right up until Vex's Headshot. Smoke Bomb did more for this fight than the scoreboard shows. That was Bramble. Loot: 35 silver each, 14 herbs, 1 troll hide.","heroes":["h13","h7"],"parties":["p1"],"loc":"bleakmarsh","fight":"f261","foes":["swamp_troll","swamp_troll","bog_crawler"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"place","reworded":-16},{"id":"e2841","day":80,"season":3,"sday":20,"kind":"talent","imp":1,"text":"Bramble bets the Ashfen tavern a round that they can put an arrow through the knot in the far beam. The knot is now a hole. Wager Shot all the way, Bramble insists.","heroes":["h13"],"parties":["p1"],"loc":"ashfen","skill":"wager_shot","wx":"fog"},{"id":"e2878","day":81,"season":3,"sday":21,"kind":"bounty","imp":2,"text":"The guild clerk in Carrbridge counts out bounties for The Newts of Ashfen until the cashbox is empty: 88 silver each.","heroes":["h13"],"parties":["p1"],"loc":"carrbridge","amount":88,"wx":"rain"},{"id":"e2892","day":81,"season":3,"sday":21,"kind":"goal_progress","imp":2,"text":"The Newts of Ashfen are getting close: earn 1,700 silver between them before the season ends (1,135 of 1,700 silver).","heroes":["h13","h7"],"parties":["p1"]},{"id":"e2952","day":83,"season":3,"sday":23,"kind":"ability","imp":2,"text":"Vex hitches a ride on a hay cart she knew would be passing at noon, naps all the way, and steps off healed and smiling.","heroes":["h7"],"parties":["p1"],"loc":"ironhaven","skill":"walker_of_all_roads","sk":"Walker of All Roads","rule":true,"wx":"rain"},{"id":"e2980","day":84,"season":3,"sday":24,"kind":"talent","imp":2,"text":"Vex overhears two merchants at the Frosthold tavern discussing a price rise, and gets in first.","heroes":["h7"],"parties":["p1"],"loc":"frosthold","skill":"eavesdropper","wx":"fog"},{"id":"e3011","day":85,"season":3,"sday":25,"kind":"talent","imp":1,"text":"A Veldrock fisherman offers Bramble a job. They are better at waiting than anyone on the pier.","heroes":["h13"],"parties":["p1"],"loc":"veldrock","skill":"still_as_a_heron","wx":"fog"},{"id":"e3013","day":85,"season":3,"sday":25,"kind":"talent","imp":1,"text":"Vex knows the back way from one end of Veldrock to the other in a third of the time.","heroes":["h7"],"parties":["p1"],"loc":"veldrock","skill":"couriers_coin","wx":"fog"},{"id":"e3015","day":85,"season":3,"sday":25,"kind":"argument","imp":2,"text":"Vex and Bramble spend supper disagreeing about whose turn it was to keep watch, politely at first.","heroes":["h7","h13"],"parties":["p1"]},{"id":"e3036","day":86,"season":3,"sday":26,"kind":"ability","imp":2,"text":"A hare sits up in the grass at Emberdeep, looks right at Bramble, and decides Bramble is a stump. Supper. By morning a pelt is stretched to dry on a frame.","heroes":["h13"],"parties":["p1"],"loc":"emberdeep","skill":"still_as_a_heron","sk":"Still as a Heron","rule":true,"wx":"fog"},{"id":"e3044","day":86,"season":3,"sday":26,"kind":"meet","imp":2,"text":"Vex and Ottoline swap stories in Emberdeep while The Newts of Ashfen and Ottoline swap rumours.","heroes":["h13","h7","h14"],"parties":["p1"],"loc":"emberdeep","wx":"fog"},{"id":"e3045","day":86,"season":3,"sday":26,"kind":"talent","imp":1,"text":"Bramble stands perfectly still while a giant spider walks past. It never notices. Still as a Heron, the guild calls it.","heroes":["h13"],"parties":["p1"],"loc":"emberdeep","skill":"still_as_a_heron","wx":"fog"},{"id":"e3053","day":86,"season":3,"sday":26,"kind":"talent","imp":1,"text":"Vex names every star over the camp by which road it hangs above. (Walker of All Roads, if anyone's asking.)","heroes":["h7"],"parties":["p1"],"loc":"emberdeep","skill":"walker_of_all_roads","wx":"fog"},{"id":"e3058","day":87,"season":3,"sday":27,"kind":"delve","imp":1,"text":"The Newts of Ashfen descend into Emberdeep, barely touched (2%).","heroes":["h13","h7"],"parties":["p1"],"loc":"emberdeep","wx":"fog"},{"id":"e3059","day":87,"season":3,"sday":27,"kind":"fight","imp":2,"text":"Bramble hits hardest as the Newts of Ashfen cut down 3 Salamanders and a Fire Elemental on floor 1 of Emberdeep. The last salamander breaks and runs. Bramble's Keyhole Shot was where the fight changed hands. Vex kept them off everyone with High Ground. Loot: 4 ember cores, 11 salamander tails, 1 trinket. Vex, who has been afraid of fire since childhood, does not run. Nobody says anything. Everybody noticed.","heroes":["h13","h7"],"parties":["p1"],"loc":"emberdeep","fight":"f272","foes":["salamander","salamander","fire_elemental"],"where":"on floor 1 of Emberdeep","won":true,"close":false,"shape":"hero","reworded":-34,"wx":"fog"},{"id":"e3095","day":88,"season":3,"sday":28,"kind":"fight","imp":2,"text":"Two Drakes and a Salamander make the mistake of going for the Newts of Ashfen on floor 2 of Emberdeep. Vex put Pinning Shot into the drake to end it, and lowered the bow. Loot: 6 drake scales, 4 fangs & claws, 3 drake flanks.","heroes":["h13","h7"],"parties":["p1"],"loc":"emberdeep","fight":"f276","foes":["salamander","drake","drake"],"where":"on floor 2 of Emberdeep","won":true,"close":false,"shape":"foe","reworded":-23,"wx":"fog"},{"id":"e3103","day":88,"season":3,"sday":28,"kind":"meet","imp":2,"text":"The Green Mercy and The Newts of Ashfen share a fire in Emberdeep. Tamsin shares jerky.","heroes":["h19","h20","h10","h16","h13","h7"],"parties":["p6","p1"],"loc":"emberdeep","wx":"fog"},{"id":"e3131","day":89,"season":3,"sday":29,"kind":"fight","imp":2,"text":"The Newts of Ashfen cut down a Lava Golem and a Fire Elemental on floor 3 of Emberdeep. Bramble ended it the plain way: Pan to the Face, and the lava golem on the ground. High Ground did more for this fight than the scoreboard shows. That was Vex. Loot: 6 ember cores, 30 ore.","heroes":["h13","h7"],"parties":["p1"],"loc":"emberdeep","fight":"f277","foes":["lava_golem","fire_elemental"],"where":"on floor 3 of Emberdeep","won":true,"close":false,"shape":"plain","wx":"snow"},{"id":"e3141","day":89,"season":3,"sday":29,"kind":"meet","imp":2,"text":"The Mercy of Thornwall runs into The Newts of Ashfen in Emberdeep. Stories are exchanged, most of them exaggerated.","heroes":["h17","h11","h1","h14","h13","h7"],"parties":["p4","p1"],"loc":"emberdeep","wx":"snow"},{"id":"e3172","day":90,"season":3,"sday":30,"kind":"fight","imp":2,"text":"Floor 4 of Emberdeep turns up a Fire Elemental and a Lava Golem, and the Newts of Ashfen cut them down. The fire elemental had been trouble right up until Vex's Headshot. Loot: 4 ember cores, 25 ore, 1 gem. Injured: Bramble (concussion).","heroes":["h13","h7"],"parties":["p1"],"loc":"emberdeep","fight":"f280","foes":["fire_elemental","lava_golem"],"where":"on floor 4 of Emberdeep","won":true,"close":false,"shape":"place","reworded":-16,"wx":"snow"},{"id":"e3183","day":90,"season":3,"sday":30,"kind":"talent","imp":1,"text":"The Silver-Thread Scarf flutters by the fire, though there's no wind.","heroes":["h13"],"parties":["p1"],"loc":"emberdeep","wx":"snow"},{"id":"e3193","day":90,"season":3,"sday":30,"kind":"delve_done","imp":1,"text":"The Newts of Ashfen come up after 4 days in Emberdeep. They got down to floor 4, mapped 28% of it and disarmed 1 trap. Counting everyone's digging, Emberdeep is mostly unexplored (13%).","heroes":["h13","h7"],"parties":["p1"],"loc":"emberdeep","days":4,"bottom":false,"rooms":[],"gold":0,"wx":"snow"},{"id":"e3199","day":90,"season":3,"sday":30,"kind":"goal_missed","imp":3,"text":"Season's end, and The Newts of Ashfen came up short: earn 1,700 silver between them before the season ends (1,408 of 1,700 silver).","heroes":["h13","h7"],"parties":["p1"]},{"id":"e3208","day":90,"season":3,"sday":30,"kind":"vow_kept","imp":4,"text":"VOWS KEPT TO THE END OF THE AGE: The Newts of Ashfen, to share every coin (sworn in season 2); Amber Banner, to die rich (sworn in season 2); The Mercy of Thornwall, to keep the peace: never draw first on another hero (sworn in season 2); The Mercy of Thornwall, to die rich (sworn in season 2); The Black Vanguard, never to retreat (sworn in season 2); The Green Mercy, to keep the peace: never draw first on another hero (sworn in season 1); Vex, to keep the peace: never draw first on another hero (sworn in season 1). Every one of them held.","heroes":["h7"],"parties":["p1","p2","p4","p5","p6"]}],"roles":{"h13":"Blade","h7":"Leader · Scout"},"quest":{"what":"Delve","where":"Emberdeep","why":"chasing a rumour: about 31 silver a day each, risk real; the season goal: to earn 1,700 silver between them before the season ends","floor":3,"floors":5},"tactics":{"front":[],"back":["h13","h7"],"plan":"Bramble and Vex pick off whatever gets close.","traits":{"boldness":0.13,"risk":-0.15,"greed":-0.2,"sociability":-0.48,"honor":0.68,"curiosity":0.5,"temper":-0.29,"loyalty":-0.34},"mix":"2 bows","notes":["Nobody wants the front row. Whoever's nearest takes the hits.","No healer: every wound comes home with them."],"style":["skirmishers"],"skills":[{"label":"Damage","skills":[{"hero":"h7","id":"pinning_shot","name":"Pinning Shot","desc":"Nails a sleeve to a tree.","tags":["crit","nature"],"rank":3,"uses":51},{"hero":"h13","id":"pinning_shot","name":"Pinning Shot","desc":"Nails a sleeve to a tree.","tags":["crit","nature"],"rank":1,"uses":44},{"hero":"h13","id":"pan_to_the_face","name":"Pan to the Face","desc":"The frying pan was for cooking. Was.","tags":[],"rank":1,"uses":26},{"hero":"h13","id":"keyhole_shot","name":"Keyhole Shot","desc":"Through the visor slot, at forty paces, in the rain.","tags":["crit"],"rank":2,"uses":20},{"hero":"h7","id":"headshot","name":"Headshot","desc":"Between the eyes.","tags":["crit"],"rank":1,"uses":13}]},{"label":"Tricks","skills":[{"hero":"h7","id":"high_ground","name":"High Ground","desc":"Got the crew up the hill before the fight knew it was a fight.","tags":["nature","travel"],"rank":3,"uses":39},{"hero":"h13","id":"smoke_bomb","name":"Smoke Bomb","desc":"Cough. Gone.","tags":["stealth"],"rank":2,"uses":30},{"hero":"h13","id":"camouflage","name":"Camouflage","desc":"Becomes a bush. A suspicious bush.","tags":["stealth","nature"],"rank":1,"uses":2},{"hero":"h13","id":"the_last_arrow","name":"The Last Arrow","desc":"Bleeding, out of time, one arrow left. Their favourite odds.","tags":[],"rank":1,"uses":1}]},{"label":"Always on","skills":[{"hero":"h13","id":"shadowstep","name":"Shadowstep","desc":"Steps into one shadow and out of another.","tags":["stealth"],"rank":2,"uses":0},{"hero":"h13","id":"evasive","name":"Evasive","desc":"Hard to pin down.","tags":["stealth"],"rank":2,"uses":0},{"hero":"h13","id":"lucky","name":"Lucky","desc":"Things just work out.","tags":["crit"],"rank":2,"uses":0},{"hero":"h7","id":"lay_of_the_land","name":"Lay of the Land","desc":"Fights on ground they walked yesterday.","tags":["nature","travel"],"rank":2,"uses":0},{"hero":"h7","id":"trail_sense","name":"Trail Sense","desc":"Never trips. Has never had to look down.","tags":["travel"],"rank":2,"uses":0}]},{"label":"On the road","skills":[{"hero":"h13","id":"trapfinder","name":"Trapfinder","desc":"Steps around the flagstone everyone else steps on.","tags":["stealth"],"rank":2,"uses":0},{"hero":"h13","id":"trapper","name":"Trapper","desc":"Sets snares at dusk, checks them at dawn.","tags":["nature","beast"],"rank":1,"uses":0},{"hero":"h13","id":"whittler","name":"Whittling","desc":"Turns every stick into a small duck.","tags":[],"rank":1,"uses":0},{"hero":"h13","id":"pest_control","name":"Pest Control","desc":"Farmers pay them to shoot the crows. The crows are said to be making a counter-offer.","tags":["crit"],"rank":1,"uses":0},{"hero":"h13","id":"wager_shot","name":"Wager Shot","desc":"Bets the tavern it can split the apple. The apple has lost every time.","tags":["crit"],"rank":2,"uses":0},{"hero":"h13","id":"eagle_eye","name":"Eagle Eye","desc":"Spots the bandit before the bandit spots the road.","tags":["crit"],"rank":1,"uses":0},{"hero":"h13","id":"lockpicking","name":"Lockpicking","desc":"Doors are suggestions.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h13","id":"devout","name":"Devout","desc":"Temples patch them up for less.","tags":["holy"],"rank":1,"uses":0},{"hero":"h7","id":"trailblazer","name":"Trailblazer","desc":"Cuts a day off long roads.","tags":["travel"],"rank":3,"uses":0},{"hero":"h7","id":"barterer","name":"Barterer","desc":"Will swap you anything for anything.","tags":["trade","travel"],"rank":2,"uses":0},{"hero":"h7","id":"trail_baker","name":"Trail Baker","desc":"Bread on the road. Actual bread.","tags":[],"rank":1,"uses":0},{"hero":"h7","id":"bulk_trader","name":"Bulk Trader","desc":"Buys a mule. Then another.","tags":["trade","travel"],"rank":1,"uses":0},{"hero":"h7","id":"spelunker","name":"Spelunker","desc":"Happiest in a crack the width of a loaf.","tags":["travel","stealth"],"rank":1,"uses":0},{"hero":"h7","id":"eavesdropper","name":"Eavesdropper","desc":"Always sits near the important tables.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h7","id":"cartography","name":"Cartography","desc":"Draws the map as they walk it.","tags":["travel"],"rank":2,"uses":0},{"hero":"h7","id":"packmule","name":"Packmule","desc":"Carries half again as much.","tags":[],"rank":1,"uses":0},{"hero":"h7","id":"quiet_road","name":"The Quiet Road","desc":"Takes the road the bandits forgot about.","tags":["travel","nature"],"rank":1,"uses":0}]}],"share":[{"hero":"h13","dmg":6182,"healed":0,"taken":319,"kills":19,"row":"back"},{"hero":"h7","dmg":4199,"healed":0,"taken":229,"kills":17,"row":"back"}],"ground":{"name":"Bleakmarsh","fights":13}},"trophies":[{"boss":"Vessimir the Unburied","monster":"necromancer","place":"The Ashveil Crypts","day":26,"season":1,"fight":"f102"}]};